True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = {v for v in range(w) if len({grid[r][v] for r in range(h)}) == 1 and grid[0][v] != 9}
    for r in range(h):
        if len(set(grid[r])) == 1:
            for c in range(w): out[r][c] = 2
    for c in bars:
        for r in range(h):
            if grid[r][c] != 9: out[r][c] = 2
    return out
